"use client";

import React, { useState } from "react";
import { 
  Calendar, Clock, Filter, Trash2, Edit2, MoreVertical, 
  CheckCircle2, XCircle, AlertCircle, ArrowUpRight, Plus
} from "lucide-react";

// --- MOCK DATA ---
const MY_LEAVES = [
  {
    id: "LR002",
    type: "Sick Leave",
    startDate: "2026-01-20",
    endDate: "2026-01-22",
    days: 3,
    reason: "Severe viral fever and fatigue",
    status: "Approved",
    appliedOn: "2026-01-18",
  },
  {
    id: "LR003",
    type: "Casual Leave",
    startDate: "2026-02-14",
    endDate: "2026-02-14",
    days: 1,
    reason: "Personal commitment",
    status: "Pending",
    appliedOn: "2026-02-01",
  },
  {
    id: "LR004",
    type: "Annual Leave",
    startDate: "2025-12-20",
    endDate: "2025-12-30",
    days: 10,
    reason: "Winter family vacation",
    status: "Rejected",
    appliedOn: "2025-11-15",
  },
];

const LEAVE_BALANCES = [
  { type: "Annual", total: 18, used: 10, color: "bg-blue-500" },
  { type: "Sick", total: 12, used: 3, color: "bg-rose-500" },
  { type: "Casual", total: 6, used: 1, color: "bg-amber-500" },
];

export default function PremiumManageAbsence() {
  const [requests, setRequests] = useState(MY_LEAVES);
  const [filter, setFilter] = useState("All");

  const handleCancel = (id: string) => {
    if (confirm("Revoke this leave request?")) {
      setRequests(prev => prev.filter(req => req.id !== id));
    }
  };

  const getStatusStyle = (status: string) => {
    switch (status) {
      case "Approved": return "bg-emerald-50 text-emerald-600 border-emerald-100 dark:bg-emerald-500/10 dark:text-emerald-400 dark:border-emerald-500/20";
      case "Rejected": return "bg-rose-50 text-rose-600 border-rose-100 dark:bg-rose-500/10 dark:text-rose-400 dark:border-rose-500/20";
      case "Pending": return "bg-amber-50 text-amber-600 border-amber-100 dark:bg-amber-500/10 dark:text-amber-400 dark:border-amber-500/20";
      default: return "bg-gray-50 text-gray-600";
    }
  };

  const StatusIcon = ({ status }: { status: string }) => {
    switch (status) {
      case "Approved": return <CheckCircle2 size={16} />;
      case "Rejected": return <XCircle size={16} />;
      case "Pending": return <Clock size={16} />;
      default: return <AlertCircle size={16} />;
    }
  };

  // Helper to replace date-fns
  const getDay = (dateStr: string) => new Date(dateStr).getDate();
  const getMonth = (dateStr: string) => new Date(dateStr).toLocaleString('default', { month: 'short' });

  return (
    <div className="min-h-screen bg-gray-50/50 dark:bg-[#09090b] p-6 lg:p-10 font-sans">
      <div className="max-w-5xl mx-auto space-y-8">
        
        {/* 1. HEADER SECTION */}
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div>
            <h1 className="text-3xl font-bold tracking-tight text-gray-900 dark:text-white">My Absences</h1>
            <p className="text-gray-500 dark:text-gray-400 mt-1">Track your history and manage upcoming time off.</p>
          </div>
          <button className="inline-flex items-center gap-2 bg-gray-900 dark:bg-white text-white dark:text-black px-5 py-2.5 rounded-full font-semibold text-sm shadow-xl hover:scale-105 transition-transform">
            <Plus size={16} />
            New Request
          </button>
        </div>

        {/* 2. BALANCE CARDS (Visual Dashboard) */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          {LEAVE_BALANCES.map((bal) => (
            <div key={bal.type} className="group relative overflow-hidden bg-white dark:bg-[#121212] border border-gray-100 dark:border-white/5 rounded-2xl p-5 shadow-sm hover:shadow-md transition-all">
              <div className={`absolute top-0 left-0 w-1 h-full ${bal.color}`} />
              <div className="flex justify-between items-start mb-4">
                <div>
                  <p className="text-xs font-bold text-gray-400 uppercase tracking-wider">{bal.type} Balance</p>
                  <h3 className="text-2xl font-black text-gray-900 dark:text-white mt-1">{bal.total - bal.used} <span className="text-sm font-medium text-gray-400">/ {bal.total} days</span></h3>
                </div>
                <div className={`p-2 rounded-lg bg-gray-50 dark:bg-white/5 ${bal.color.replace('bg-', 'text-')}`}>
                  <ArrowUpRight size={18} />
                </div>
              </div>
              {/* Progress Bar */}
              <div className="w-full bg-gray-100 dark:bg-gray-800 h-1.5 rounded-full overflow-hidden">
                <div 
                  className={`h-full ${bal.color} transition-all duration-1000 ease-out`} 
                  style={{ width: `${(bal.used / bal.total) * 100}%` }} 
                />
              </div>
            </div>
          ))}
        </div>

        {/* 3. FILTERS & LIST */}
        <div className="space-y-4">
          {/* Toolbar */}
          <div className="flex items-center justify-between bg-white dark:bg-[#121212] p-2 rounded-xl border border-gray-100 dark:border-white/5 shadow-sm">
            <div className="flex gap-1">
              {["All", "Pending", "Approved", "Rejected"].map(f => (
                <button
                  key={f}
                  onClick={() => setFilter(f)}
                  className={`px-4 py-1.5 rounded-lg text-sm font-medium transition-all ${filter === f ? "bg-gray-100 dark:bg-white/10 text-gray-900 dark:text-white" : "text-gray-500 hover:text-gray-700 dark:hover:text-gray-300"}`}
                >
                  {f}
                </button>
              ))}
            </div>
            <div className="px-3 text-gray-400">
              <Filter size={16} />
            </div>
          </div>

          {/* Request List */}
          <div className="space-y-3">
            {requests
              .filter(r => filter === "All" || r.status === filter)
              .map((req) => (
              <div 
                key={req.id} 
                className="group relative bg-white dark:bg-[#121212] rounded-2xl p-5 border border-gray-100 dark:border-white/5 shadow-sm hover:border-blue-500/30 transition-all flex flex-col md:flex-row gap-6 items-start md:items-center"
              >
                {/* Date Box */}
                <div className="flex-shrink-0 flex flex-col items-center justify-center bg-gray-50 dark:bg-white/5 rounded-xl w-16 h-16 border border-gray-100 dark:border-white/5">
                   <span className="text-xs font-bold text-gray-400 uppercase">{getMonth(req.startDate)}</span>
                   <span className="text-xl font-black text-gray-900 dark:text-white">{getDay(req.startDate)}</span>
                </div>

                {/* Details */}
                <div className="flex-grow space-y-1">
                  <div className="flex items-center gap-3">
                    <h3 className="font-bold text-gray-900 dark:text-white text-lg">{req.type}</h3>
                    <span className={`inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full text-xs font-bold border ${getStatusStyle(req.status)}`}>
                      <StatusIcon status={req.status} />
                      {req.status}
                    </span>
                  </div>
                  <div className="flex items-center gap-4 text-sm text-gray-500 dark:text-gray-400">
                    <div className="flex items-center gap-1.5">
                      <Calendar size={14} />
                      <span>{req.startDate} — {req.endDate}</span>
                    </div>
                    <div className="w-1 h-1 rounded-full bg-gray-300" />
                    <span>{req.days} Day{req.days > 1 ? 's' : ''}</span>
                  </div>
                  <p className="text-sm text-gray-600 dark:text-gray-300 mt-2 line-clamp-1 italic">
                    "{req.reason}"
                  </p>
                </div>

                {/* Actions */}
                <div className="flex items-center gap-2 md:opacity-0 group-hover:opacity-100 transition-opacity">
                  {req.status === "Pending" && (
                    <>
                      <button className="p-2 rounded-lg hover:bg-blue-50 text-blue-600 dark:hover:bg-blue-500/10 transition-colors tooltip" title="Edit Request">
                        <Edit2 size={18} />
                      </button>
                      <button onClick={() => handleCancel(req.id)} className="p-2 rounded-lg hover:bg-rose-50 text-rose-600 dark:hover:bg-rose-500/10 transition-colors" title="Delete Request">
                        <Trash2 size={18} />
                      </button>
                    </>
                  )}
                  {req.status !== "Pending" && (
                    <button className="p-2 rounded-lg hover:bg-gray-100 dark:hover:bg-white/5 text-gray-400 transition-colors">
                        <MoreVertical size={18} />
                    </button>
                  )}
                </div>
              </div>
            ))}

            {requests.length === 0 && (
              <div className="text-center py-20 bg-white dark:bg-[#121212] rounded-2xl border border-dashed border-gray-200 dark:border-white/10">
                 <div className="inline-flex items-center justify-center w-12 h-12 rounded-full bg-gray-50 dark:bg-white/5 mb-3 text-gray-400">
                    <Calendar size={24} />
                 </div>
                 <h3 className="text-gray-900 dark:text-white font-medium">No leaves found</h3>
                 <p className="text-gray-500 text-sm">You haven't applied for any leave yet.</p>
              </div>
            )}
          </div>
        </div>

      </div>
    </div>
  );
}